21	std::complex<double> atree(const std::string& st,
22	                            int j1, int j2, int j3, int j4, int j5, int j6,
23	                            FArray2D<std::complex<double>>& za,
24	                            FArray2D<std::complex<double>>& zb) {
25	
26	  // Statement function 'tree' translated to a C++ lambda.
27	  // Implements BDKW Eq.(3.10) for the pp (all-right-handed) configuration;
28	  // pm and sl are obtained by crossing via the caller below.
29	  // t(i1,i2,i3) = s(i1,i2)+s(i2,i3)+s(i1,i3) from W1jet.
30	  auto tree = [&](int i1, int i2, int i3, int i4, int i5, int i6) -> std::complex<double> {
31	    return
32	        +zb(i1,i2)*za(i5,i4)*(za(i3,i1)*zb(i1,i6)+za(i3,i2)*zb(i2,i6))
33	        / (s(i2,i3)*s(i5,i6)*t(i1,i2,i3))  // @coverage-probe
34	        +za(i3,i4)*zb(i6,i1)*(za(i5,i3)*zb(i3,i2)+za(i5,i4)*zb(i4,i2))
35	        / (s(i2,i3)*s(i5,i6)*t(i2,i3,i4));
36	  };
37	
38	  std::complex<double> result;
39	  if (st == "pp") {
40	    result = +tree(j1,j2,j3,j4,j5,j6);
41	  } else if (st == "pm") {
42	    result = -tree(j1,j3,j2,j4,j5,j6);
43	  } else if (st == "sl") {
44	    // not a real tree amplitude, but an auxiliary quantity
45	    result = -tree(j3,j1,j2,j4,j5,j6);
46	  }
47	  return result;
48	}
