69	template <typename T>
70	class FArray2D {
71	
72	  private:
73	    bool ownsData;
74	    int start_i, start_j;
75	
76	  public:
77	    size_t ni, nj;
78	    T* data;
79	
80	    // Constructor to allocate memory
81	    FArray2D(size_t ni, size_t nj, int start_i=1, int start_j=1)
82	        : ni(ni), nj(nj), start_i(start_i), start_j(start_j), data(new T[ni * nj]), ownsData(true) {}
83	
84	    // Constructor to use existing Fortran array
85	    FArray2D(T* fortranArray, size_t ni, size_t nj, int start_i=1, int start_j=1)
86	        : ni(ni), nj(nj), start_i(start_i), start_j(start_j), data(fortranArray), ownsData(false) {}
87	
88	    // Destructor to free memory
89	    ~FArray2D() {
90	        if (data != nullptr && ownsData) {
91	            delete[] data;
92	        }
93	    }
94	
95	    // Access operator
96	    T& operator()(size_t i, size_t j) {
97	        return data[i-start_i + ni*(j-start_j)];
98	    }
99	
100	    // Const access operator
101	    const T& operator()(size_t i, size_t j) const {
102	        return data[i-start_i + ni*(j-start_j)];
103	    }
104	
105	    // Method to attach an existing Fortran array
106	    void attach(T* fortranArray) {
107	        data = fortranArray;
108	        ownsData = false;
109	    }
110	
111	    void fill(const T& value) {
112	        for (size_t j=start_j; j<nj+start_j; j++) {
113	            for (size_t i=start_i; i<ni+start_i; i++) {
114	                (*this)(i, j) = value;
115	            }
116	        }
117	    }
118	};
